class Base {
  tag: string;
  isBase: boolean;
  constructor() {
    this.isBase = new.target === Base;
    const read = () => new.target.name;
    this.tag = read();
    if (new.target === undefined) throw new Error("never");
  }
}
class Mid extends Base {}
class Leaf extends Mid {
  constructor() {
    super();
    Object.setPrototypeOf(this, Leaf.prototype);
  }
}
function show(o: Base): void {
  console.log(o.tag, o.isBase, o instanceof Base, o instanceof Mid, o instanceof Leaf);
}
function main(): void {
  show(new Base()); show(new Mid()); show(new Leaf());
}
